insert into public.requirement_items (service_id, text, status, created_by)
select s.id, d.value, 'approved', null from public.services s, jsonb_array_elements_text(s.docs) d
where s.id in ('lic_industrial', 'lic_cosmetics', 'lic_agro', 'lic_restaurant', 'lic_pharmacy', 'lic_hotel', 'lic_holiday_homes', 'lic_transport',
  'lic_nursery', 'lic_training', 'lic_school', 'lic_recruitment', 'lic_insurance_broker', 'lic_payments', 'lic_media', 'lic_outdoor_ads');
-- The insert guard marks new items pending; these come from the platform itself.
update public.requirement_items set status = 'approved'
where created_by is null and status = 'pending' and service_id like 'lic\_%';
